import re

def gitignore_match(pattern, path):
    is_dir_pattern = pattern.endswith('/')
    if is_dir_pattern and not path.endswith('/'):
        return False

    is_anchored = '/' in pattern[:-1]
    p = pattern[:-1] if is_dir_pattern else pattern
    path_for_regex = path[:-1] if is_dir_pattern else path

    if p == "**":
        if is_anchored:
            regex = "^.*$"
        else:
            regex = "^.*$"
    else:
        # Handle double star first to avoid conflicts with single star
        p = p.replace('**', '___DBL___')
        p = re.escape(p)
        # Fix escaped special characters
        p = p.replace('___DBL___', '.*')
        p = p.replace(r'\*', '[^/]*')
        p = p.replace(r'\?', '[^/]')
        p = p.replace(r'\[', '[').replace(r'\]', ']')

        if is_dir_pattern:
            p = p + r'(?:/.*)?'

        if is_anchored:
            regex = "^" + p + "$"
        else:
            regex = r"(^|/)" + p + "$"

    return bool(re.match(regex, path_for_regex))
