def parse_range(header, size):
    if not isinstance(header, str) or not header:
        return None

    ranges = []
    for part in header.split(','):
        part = part.strip()
        if not part:
            continue

        if '-' not in part:
            return None

        sub_parts = part.split('-', 1)
        p1 = sub_parts[0].strip()
        p2 = sub_parts[1].strip()

        try:
            if p1 != '' and p2 != '':
                # Case: bytes=<start>-<end>
                start = int(p1)
                end = int(p2)
                if start <= end and start < size:
                    ranges.append((start, min(end, size - 1)))
            elif p1 != '':
                # Case: bytes=<start>-
                start = int(p1)
                if start < size:
                    ranges.append((start, size - 1))
            elif p2 != '':
                # Case: bytes=-<suffix>
                suffix = int(p2)
                if size > 0:
                    start = max(0, size - suffix)
                    ranges.append((start, size - 1))
                else:
                    # If size is 0, suffix-based ranges are unsatisfiable
                    pass
            else:
                # Case: "-" which is malformed
                return None
        except ValueError:
            # Non-integer values are malformed
            return None

    return ranges if ranges else None
