    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    diff_ops = []
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i - 1] == b[j - 1]:
            diff_ops.append(('eq', i - 1, j - 1))
            i -= 1
            j -= 1
        elif i > 0 and (j == 0 or dp[i - 1][j] >= dp[i][j - 1]):
            diff_ops.append(('del', i - 1))
            i -= 1
        else:
            diff_ops.append(('ins', j - 1))
            j -= 1
    diff_ops.reverse()

    dirty_indices = [idx for idx, op in enumerate(diff_ops) if op[0] != 'eq']
    if not dirty_indices:
