import re

def parse_duration(s):
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    sign = 1
    if s.startswith('-'):
        sign = -1
        s = s[1:]

    if not s.startswith('P'):
        raise ValueError("Invalid duration format")

    # Regex to capture Y, M, D, H, M, S components
    # The time part (T) and its components are optional, but T itself must be followed by components
    pattern = r'^P(?:(\d+)Y)?(?:(\d+)M)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+(?:\.\d+)?)S)?)?$'
    match = re.match(pattern, s)

    if not match:
        raise ValueError("Invalid duration format")

    y, m_year, d, h, m_min, s_val = match.groups()

    # Rule: T must be absent if no time fields follow
    if 'T' in s and h is None and m_min is None and s_val is None:
        raise ValueError("T must be followed by time components")

    # Rule: At least one component must be present
    if all(v is None for v in (y, m_year, d, h, m_min, s_val)):
        raise ValueError("At least one component must be provided")

    total_seconds = 0.0

    # Using constants: 1 year = 365 days, 1 month = 30 days
    if y is not None:
        total_seconds += int(y) * 365 * 24 * 3600
    if m_year is not None:
        total_seconds += int(m_year) * 30 * 24 * 3600
    if d is not None:
        total_seconds += int(d) * 24 * 3600
    if h is not None:
        total_seconds += int(h) * 3600
    if m_min is not None:
        total_seconds += int(m_min) * 60
    if s_val is not None:
        total_seconds += float(s_val)

    return sign * total_seconds
