    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def consume(self, expected=None):
            token = self.peek()
            if token is None:
                raise ValueError("Unexpected end of expression")
            if expected and token != expected:
                raise ValueError(f"Expected {expected}, found {token}")
            self.pos += 1
            return token

        def expression(self):
            node = self.term()
            while self.peek() in ('+', '-'):
                op = self.consume()
                right = self.term()
                if op == '+':
                    node += right
                else:
                    node -= right
            return node

        def term(self):
            node = self.unary()
            while self.peek() in ('*', '/', '%'):
                op = self.consume()
                right = self.unary()
                if op == '*':
                    node *= right
                elif op == '/':
                    if right == 0:
                        raise ValueError("Division by zero")
                    node /= right
                elif op == '%':
                    if right == 0:
                        raise ValueError("Division by zero")
                    node %= right
            return node

        def unary(self):
            if self.peek() == '+':
                self.consume()
                return self.unary()
            elif self.peek() == '-':
                self.consume()
                return -self.unary()
            else:
                return self.power()

        def power(self):
            node = self.primary()
            if self.peek() == '**':
                self.consume()
                node = node ** self.unary()
            return node

        def primary(self):
            token = self.peek()
            if token == '(':
                self.consume()
                node = self.expression()
                self.consume(')')
                return node
            elif token is not None and (isinstance(token, float) or isinstance(token, int)):
                return self.consume()
            else:
                raise ValueError(f"Unexpected token: {token}")

    def tokenize(s):
