                i += 1
                continue
            if s[i:i+2] == '**':
                tokens.append('**')
                i += 2
            elif s[i] in '+-*/%()':
                tokens.append(s[i])
                i += 1
            elif s[i].isdigit() or s[i] == '.':
                j = i
