                    j += 1
                num_str = s[i:j]
                if num_str.count('.') > 1:
                    raise ValueError("Invalid number")
                try:
                    tokens.append(float(num_str))
                except ValueError:
                    raise ValueError("Invalid number")
                i = j
            else:
                raise ValueError(f"Invalid character: {s[i]}")
        return tokens

