def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]

    base = len(alphabet)
    is_negative = n < 0
    n = abs(n)
    digits = []

    while n > 0:
        digits.append(alphabet[n % base])
        n //= base

    if is_negative:
        digits.append('-')

    return "".join(reversed(digits))

def from_base(s, alphabet):
