    start_idx = 0
    sign = 1
    if s[0] == '-':
        sign = -1
        start_idx = 1
        if len(s) == 1:
            raise ValueError("Invalid string")

    res = 0
    for i in range(start_idx, len(s)):
        char = s[i]
        if char not in char_to_val:
            raise ValueError(f"Character {char} not in alphabet")
        res = res * base + char_to_val[char]

    return sign * res
