    const list = this._events.get(event);
    if (list) {
      const index = list.findIndex((l) => l.fn === fn);
      if (index !== -1) {
        list.splice(index, 1);
      }
    }
  }

  emit(event, ...args) {
    const list = this._events.get(event);
    if (!list) return 0;

    const snapshot = [...list];
    let invokedCount = 0;
    let firstError = null;

    for (const item of snapshot) {
      if (!list.includes(item)) continue;

      invokedCount++;

      if (item.once) {
        const index = list.indexOf(item);
        if (index !== -1) {
          list.splice(index, 1);
        }
      }

      try {
        item.fn(...args);
      } catch (err) {
        if (!firstError) {
          firstError = err;
        }
      }
    }

    if (firstError) {
      throw firstError;
    }

    return invokedCount;
  }
