  for (const name of names) {
    for (const dep of tasks[name].deps) {
      if (!(dep in tasks)) {
        return Promise.reject(new Error(`Unknown dependency: ${dep}`));
      }
    }
  }

  const visited = new Set();
  const recStack = new Set();
  function hasCycle(u) {
