    recStack.add(u);
    for (const v of tasks[u].deps) {
      if (!visited.has(v)) {
        if (hasCycle(v)) return true;
      } else if (recStack.has(v)) {
        return true;
      }
    }
    recStack.delete(u);
    return false;
  }

  for (const name of names) {
    if (!visited.has(name) && hasCycle(name)) {
      return Promise.reject(new Error("Dependency cycle detected"));
    }
  }

  const results = {};
  const errorMap = new Map();
  const taskPromises = {};

  const execute = async (name) => {
    const task = tasks[name];
    for (const depName of task.deps) {
      await taskPromises[depName];
