    const depValues = task.deps.reduce((acc, depName) => {
      acc[depName] = results[depName];
      return acc;
    }, {});

    try {
      results[name] = await task.run(depValues);
    } catch (err) {
      errorMap.set(name, err);
      throw err;
    }
