export class Bus<E extends Record<string, unknown>> {
  private handlers: Map<keyof E, Set<(...args: any[]) => void>> = new Map();

  on<K extends keyof E>(
    k: K,
    fn: E[K] extends void ? (() => void) : ((payload: E[K]) => void)
  ): () => void {
    let set = this.handlers.get(k);
    if (!set) {
      set = new Set();
      this.handlers.set(k, set);
    }
    set.add(fn as (payload: any) => void);
    return () => set.delete(fn as (payload: any) => void);
  }

  emit<K extends keyof E>(
    k: K,
    ...args: E[K] extends void ? [] : [E[K]]
  ): void {
    this.handlers.get(k)?.forEach((fn) => fn(...args));
  }
}
