type RequiredKeys<T> = {
  [K in keyof T as undefined extends T[K] ? never : K]: K
}[keyof T];

type MissingRequired<Config, Current> = Exclude<RequiredKeys<Config>, keyof Current>;

type Builder<Config, Current> = {
  set<K extends keyof Config>(key: K, value: Config[K]): Builder<Config, Current & { [P in K]: Config[K] }>;
} & (MissingRequired<Config, Current> extends never ? { build(): Config } : {});

function createBuilder<Config, Current>(data: Current): Builder<Config, Current> {
  return {
    set<K extends keyof Config>(key: K, value: Config[K]): Builder<Config, Current & { [P in K]: Config[K] }> {
      return createBuilder({ ...data, [key]: value } as any);
    },
    build: () => data as any,
  } as any;
}

export const builder = <Config>() => createBuilder<Config, {}>({});
