export type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends (...args: any[]) => any
  ? T
  : T extends Array<infer U>
  ? DeepAwaited<U>[]
  : T extends object
  ? { [K in keyof T]: DeepAwaited<T[K]> }
  : T;

export async function deepAwait<T>(val: T): Promise<DeepAwaited<T>> {
  if ((val as any) instanceof Promise) {
    return deepAwait(await val);
  }
  if (Array.isArray(val)) {
    return Promise.all(val.map((item) => deepAwait(item))) as any;
  }
  if (val !== null && typeof val === 'object' && typeof val !== 'function') {
    const result: any = {};
    for (const key in val) {
      if (Object.prototype.hasOwnProperty.call(val, key)) {
        result[key] = await deepAwait(val[key]);
      }
    }
    return result;
  }
  return val as any;
}
