type Curried<Args extends any[], R> = {
  <T extends Args>(...args: T): T['length'] extends Args['length']
    ? R
    : Args extends [...T, ...infer Rest]
      ? (...args: Rest) => R
      : never;
};

export function curry<Args extends any[], R>(fn: (...args: Args) => R): Curried<Args, R> {
  const arity = fn.length;
  const loop = (...args: any[]) => {
    if (args.length >= arity) {
      return fn(...args);
    }
    return loop.bind(undefined, ...args);
  };
  return loop as any;
}
