type GetParamKeys<S extends string> =
  S extends `${infer Head}/${infer Tail}`
  ? Head extends `:${infer P}`
    ? [P, ...GetParamKeys<Tail>]
    : GetParamKeys<Tail>
  : S extends `:${infer P}`
    ? [P]
    : [];

type ParamsFromPath<P extends string> =
  GetParamKeys<P> extends infer K
    ? K extends string[]
      ? { [Key in K[number]]: string }
      : {}
    : {};

type RouteFunc<P extends string> =
  GetParamKeys<P> extends []
    ? () => string
    : (params: ParamsFromPath<P> & Record<string, never>) => string;

export function defineRoutes<T extends Record<string, string>>(
  routes: T
): { [K in keyof T]: RouteFunc<T[K]> } {
  const result = {} as any;
  for (const key in routes) {
    const path = routes[key];
    const matches = path.match(/:(\w+)/g);
    if (!matches) {
      result[key] = () => path;
    } else {
      result[key] = (params: Record<string, string>) => {
        let interpolated = path;
        for (const m of matches) {
          const paramName = m.slice(1);
          interpolated = interpolated.replace(m, params[paramName]);
        }
        return interpolated;
      };
    }
  }
  return result;
}
